{
  "spells": [
    {
      "id": "spell_wind_10",
      "theory": "气囊术将魔力压入一小团空气，使其在目标口鼻外暂时维持可呼吸的薄层。这层气团依附在受术者面部附近，不与周围大气自由交换；树脂粉先撒在气流中，帮助魔力抓住气团边界。气泡内氧气有限，耗尽后便会塌缩，无法补充或过滤新空气。",
      "casting": "捏碎树脂撒向目标，手掌从口鼻外侧向内合拢，再缓缓向外撑开成球。指节保持弯曲，让魔力沿掌缘均匀分布。",
      "failure": "气团会在中途散开，受术者只感到一阵凉风，随后发现仍无法呼吸。树脂粉末可能粘在口鼻附近，引起呛咳，但不会产生新的气源。",
      "counters": [
        "用扇子或衣物大力扇动，可扰乱气团边界使其提前塌缩。",
        "将目标迅速拖离原地，气团因依附位置偏移而失效。"
      ],
      "socialConsequences": "河谷船工在翻船后常靠此术争取捞人时间，乡约见证下施救者不担责。城市公会要求施术前确认目标无传染病，避免多人共用同一气团。琥珀海岸的潜水采珠人竞争激烈，有人会故意在他人上浮时抢先施放，港务只追究是否造成实际货损或人员伤亡。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时气团只能维持极短时间，且容易偏离口鼻。",
        "熟练后气团边界更稳定，但仍受限于原有氧气总量。",
        "高熟练度可让气团贴合不同脸型，减少漏气浪费。",
        "更高熟练度仅提升撑开动作的精确度，不延长氧气上限。"
      ]
    },
    {
      "id": "spell_wind_11",
      "theory": "偏箭风在目标身侧制造一道短促的横向气流，用来扰乱飞来的轻型投射物。魔力先缠绕在树脂颗粒上，再被甩成一条弧线，与箭杆或投石擦过时改变其飞行方向。重弩矢因质量较大，只会被轻微推偏，仍可能命中。气流不追踪目标，只在施术瞬间存在。",
      "casting": "侧身站立，手臂向目标来向斜挥，树脂粒从指缝甩出。手掌在挥动末端急停，让魔力沿弧线抛出而非直冲。",
      "failure": "气流会在出手前散乱，只扬起地面尘土。来袭物不受影响，施术者可能因急停动作失去平衡，暴露在下一发投射物前。",
      "counters": [
        "改用更重的弩矢或近距离直射，可减少气流对弹道的干扰。",
        "从两个方向同时投射，偏箭风只能扰乱其中一条路线。"
      ],
      "socialConsequences": "河谷猎户在驱赶毁田野猪时使用此术，乡约允许但不许对准邻人。城市竞技场禁止在观众席附近施放，公会要求施术者自行投保流矢伤人。琥珀海岸的商船护卫常雇用会此术的人，但货主担心偏转的箭矢落入他人货堆，港务在事故后按货损追责。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时气流方向偏差大，常完全错过来袭物。",
        "熟练后能稳定偏向轻型箭矢，对重弩矢效果仍有限。",
        "高熟练度可控制气流弧线高度，减少误伤旁人的风险。",
        "更高熟练度只提升出手时机判断，不改变可偏转的投射物类型。"
      ]
    },
    {
      "id": "spell_wind_12",
      "theory": "烟雾分流将魔力注入树脂粉末，使其随风扩散成一条引导通道，把小范围烟雾引向指定出口。烟雾本身不被消灭，只是被推着走；若出口被堵，烟会回涌到施术者附近。通道依附在气流上，风停后烟雾便恢复自然扩散。",
      "casting": "面向烟雾，双手从中心向出口方向缓缓推开，树脂粉沿推势撒出。手腕保持平直，让魔力通道贴着地面或墙面延伸。",
      "failure": "通道会在半途断裂，烟雾先被推开再倒灌，可能熏到施术者自己。树脂粉若撒得不均，烟会分成几股乱窜，使原本的出口附近更呛。",
      "counters": [
        "关闭或堵住指定出口，烟雾会因无处可去而回涌。",
        "用湿布在通道中段拦截，可切断气流引导使烟重新扩散。"
      ],
      "socialConsequences": "河谷村落秋收后焚烧秸秆，乡约请会此术的人把烟引向河面，避免呛到晒谷场。城市公会要求施术前确认出口不会把烟送进邻家窗户，否则按侵扰处理。琥珀海岸的仓库失火时，港务允许用此术排烟，但若把烟引入他人货舱导致受潮，货主可索赔。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时通道弯曲易断，烟雾常半路折返。",
        "熟练后能沿墙面稳定引导，但仍需实际出口畅通。",
        "高熟练度可控制通道宽度，减少对旁边人的呛扰。",
        "更高熟练度只提升通道平顺度，不增加可引导的烟雾总量。"
      ]
    }
  ]
}
